// Icon helper for dynamically rendered markup. Static markup in index.html uses the same <svg><use> pattern.
// Icons live in assets/icons/ (Lucide, ISC licence); sprite.svg is generated by scripts/build-icon-sprite.js.
const SPRITE = 'assets/icons/sprite.svg';

/** icon('pill') → inline SVG string. Size comes from font-size (1em); colour from currentColor. */
export function icon(name, extraClass = '') {
  const cls = extraClass ? `icon ${extraClass}` : 'icon';
  return `<svg class="${cls}" aria-hidden="true" focusable="false"><use href="${SPRITE}#${name}"></use></svg>`;
}
